// Hand-written `@trpc/client` stub for the flowatlas fixture suite.
//
// The real client is a proxy whose members are inferred from the router's type, so
// `client.orders.list.query(input)` typechecks because the type system walked the
// router. A stub cannot express that and must not pretend to — so it declares the
// *kind* the real thing is, an object whose members are reached by name and whose
// leaves answer `query` and `mutate`, and says nothing about which names exist.
// Declaring less; not declaring something of another kind.

export interface TRPCLink {
  readonly _link: true;
}

export declare function httpBatchLink(options: { url: string }): TRPCLink;

/** A node of the proxy: another node under any name, or a callable leaf. */
export interface ClientNode {
  query(input?: unknown): Promise<unknown>;
  mutate(input?: unknown): Promise<unknown>;
  [name: string]: ClientNode | ((input?: unknown) => Promise<unknown>);
}

export declare function createTRPCClient<TRouter>(options: {
  links: TRPCLink[];
}): Record<string, ClientNode>;
